type TestRuntime={version:string;tasks:{id:string;kind:string;status:string;guestText:string;evidenceRefs:string[];disclosure?:string}[];preparedFacts:unknown[];artifacts:unknown[];quoteRefs:string[];packets:unknown[];errors:string[];assessment:{ok:boolean};readiness:string;textBody:string};
const hash=(text:string)=>createHash('sha256').update(text).digest('hex');
function fixture(){
 const text='Please quote two rooms and explain the cancellation policy.';
 const causalInput={threadId:'thread',trigger:{id:'case',direction:'inbound',eventAt:'2026-10-04T10:00:00Z',from:'guest@example.invalid',subject:'Quote',text,documents:[]},context:[]};
 const source=(quote:string)=>({messageId:'case',sourceHash:hash(text),start:text.indexOf(quote),end:text.indexOf(quote)+quote.length,quote});
 const obligation=(id:string,kind:string,topic:string,quote:string)=>({id,kind,semanticTopic:topic,required:true,source:source(quote),completion:{permittedTaskOutcomes:['complete','needs_clarification'],requiresSourceEvidence:['authorized_source'],focusedMissingTopics:[topic],noSuccessFromUnavailable:true,staffOnlyHandoffCountsAsComplete:false,responseObligationCanBeSatisfiedByFocusedClarification:true,sourceTaskCompletedOnlyWhenOutcomeIn:['complete'],blockedCountsAsSuccessfulResponse:false,genericHandoffCountsAsSuccessfulResponse:false},expectedFacts:[]});
 const expectation={schemaVersion:'reservationist-independent-expectations-v1',caseId:'case',inputHash:fingerprint({trigger:causalInput.trigger,context:[]}),groupId:'group',lane:'development',reviewer:{type:'independent_ai',agent:'independent-reviewer',model:'standard_inherited',reviewedAt:'2026-10-04T11:00:00Z',authorityRef:'reservationist-recovery-user-20261004',independentOfImplementationExecutor:true,crossModel:false},reviewStatus:'independently_adjudicated',modelExecutionEligible:true,historicalSourceQualificationEligible:false,eligibilityScope:'causal responses',obligations:[obligation('quote','quote','quotation','Please quote two rooms'),obligation('cancel','question','cancellation policy','cancellation policy')],evaluatorOnly:{goldId:'future',pairing:'in-reply-to',corroborationOnly:true,futureStaffResponseVisibleToReviewer:true,futureResponseMustNotEnterExecution:true,goldSourceHash:'b'.repeat(64),notes:['Booking done later cannot create success']},disagreements:[],forbiddenAssertions:[],approval:{status:'independently_adjudicated',version:'v1',reviewerRef:'independent-reviewer',sourceHashes:[hash(text)]}};
 const plan={tasks:expectation.obligations.map(o=>({id:'model-'+o.id,kind:o.kind,required:true,source:{attachmentId:'message:case',sourceHash:hash(text),page:1,start:o.source.start,end:o.source.end,quote:o.source.quote}})),facts:[]};
 const runtime:TestRuntime={version:'reservationist-runtime-v1',tasks:[{id:'model-quote',kind:'quote',status:'needs_clarification',guestText:'Please confirm the quotation stay details.',evidenceRefs:['message:case']},{id:'model-cancel',kind:'question',status:'needs_clarification',guestText:'Please confirm which cancellation policy applies.',evidenceRefs:['message:case']}],preparedFacts:[],artifacts:[],quoteRefs:[],packets:[],errors:[],assessment:{ok:true},readiness:'needs_clarification',textBody:'Please confirm the quotation stay details. Please confirm which cancellation policy applies.'};
 return {expectation,causalInput,plan,runtime};
}
async function score(value:{expectation:unknown;causalInput:unknown;plan:unknown;runtime:unknown;sourceAt?:string;currentResultObservation?:unknown}){return scoreIndependentReservationistEvaluation(value as Parameters<typeof scoreIndependentReservationistEvaluation>[0]);}
describe('independent evaluator after causal execution',()=>{
 it('counts two focused responses separately from zero completed source tasks',async()=>{const r=await score(fixture());expect(r).toMatchObject({pass:true,responseComplete:true,workComplete:false,counts:{required:2,responseSatisfied:2,workCompleted:0}});});
 it.each(['omitted','generic','blocked','staff_only','wrong_topic','wrong_hash','wrong_span','duplicate_task'])('fails %s obligation without changing its denominator',async bad=>{const f=fixture();if(bad==='omitted')f.runtime.tasks.pop();if(bad==='generic')f.runtime.tasks[1].guestText='Please confirm the details of this request so staff can verify the answer.';if(bad==='blocked')f.runtime.tasks[1].status='blocked';if(bad==='staff_only')(f.runtime.tasks[1] as typeof f.runtime.tasks[1]&{disclosure:string}).disclosure='staff_only';if(bad==='wrong_topic')f.runtime.tasks[1].guestText='Please confirm parking details.';if(bad==='wrong_hash')f.plan.tasks[1].source.sourceHash='a'.repeat(64);if(bad==='wrong_span')f.plan.tasks[1].source.start=0;if(bad==='duplicate_task')f.plan.tasks[1].id=f.plan.tasks[0].id;const r=await score(f);expect(r.pass).toBe(false);expect(r.counts.required).toBe(2);});
 it('does not turn gold changes into execution success',async()=>{const f=fixture(),a=await score(f);f.expectation.evaluatorOnly.notes=['confirmed and paid with an attached invented quotation'];f.expectation.evaluatorOnly.goldId='different';expect(await score(f)).toEqual(a);});
 it.each(['input','source','reviewer','approval'])('fails closed on %s expectation provenance',async bad=>{const f=fixture();if(bad==='input')f.expectation.inputHash='a'.repeat(64);if(bad==='source')f.expectation.obligations[0].source.quote='invented';if(bad==='reviewer')f.expectation.reviewer.independentOfImplementationExecutor=false;if(bad==='approval')f.expectation.approval.sourceHashes=[];const r=await score(f);expect(r.pass).toBe(false);expect(r.counts.required).toBe(2);});
 it('a complete quote stub without task-linked artifact or selected revision never completes work',async()=>{const f=fixture();f.runtime.tasks[0].status='complete';f.runtime.tasks[0].guestText='Please see the attached quotation.';f.runtime.tasks[0].evidenceRefs=['source'];f.runtime.textBody=f.runtime.tasks.map(t=>t.guestText).join(' ');const r=await score(f);expect(r.workComplete).toBe(false);expect(r.obligations[0].workCompleted).toBe(false);expect(r.pass).toBe(false);});
 it('never counts arbitrary pending packets as completed preparation',async()=>{const f=fixture();f.expectation.obligations=f.expectation.obligations.slice(0,1);f.expectation.obligations[0].kind='new_booking';f.expectation.obligations[0].completion.sourceTaskCompletedOnlyWhenOutcomeIn=['pending_pms_action'];f.expectation.obligations[0].completion.permittedTaskOutcomes=['pending_pms_action','needs_clarification'];f.plan.tasks=f.plan.tasks.slice(0,1);f.plan.tasks[0].kind='new_booking';f.runtime.tasks=f.runtime.tasks.slice(0,1);f.runtime.tasks[0].kind='new_booking';f.runtime.tasks[0].status='pending_pms_action';f.runtime.tasks[0].guestText='Your booking request is prepared.';(f.runtime as unknown as {packets:unknown[]}).packets=[{saved:false,status:'pending_pms_action',businessRulesValidated:true,kind:'arbitrary',taskId:f.runtime.tasks[0].id}];f.runtime.textBody=f.runtime.tasks[0].guestText;const r=await score(f);expect(r.workComplete).toBe(false);expect(r.pass).toBe(false);});
 it('real eight-case 19-obligation development envelopes retain exact source and all denominators',async()=>{const base=new URL('../../../.private/reservationist-recovery-20261004/adjudication/',import.meta.url),inputs=JSON.parse(readFileSync(new URL('development-case-inputs.json',base),'utf8')),expectations=readFileSync(new URL('independent-expectations.jsonl',base),'utf8').trim().split('\n').map(l=>JSON.parse(l));let total=0;for(const expectation of expectations){const c=inputs.find((r:{caseId:string})=>r.caseId===expectation.caseId);const r=await score({expectation,causalInput:c.causalInput,plan:{tasks:[],facts:[]},runtime:{...fixture().runtime,tasks:[]}});expect(r.provenanceValid).toBe(true);expect(r.pass).toBe(false);expect(r.counts.required).toBe(expectation.obligations.length);total+=r.counts.required;}expect(total).toBe(19);});
});

