function boardExpectationCase(value:unknown){
 const f=fixture(),text='Please quote one room including DINNER, BED & BREAKFAST.';
 f.causalInput.trigger.text=text;f.expectation.inputHash=fingerprint({trigger:f.causalInput.trigger,context:[]});f.expectation.approval.sourceHashes=[hash(text)];
 const quote='DINNER, BED & BREAKFAST',source={messageId:'case',sourceHash:hash(text),start:text.indexOf(quote),end:text.indexOf(quote)+quote.length,quote};
 f.expectation.obligations=[{...f.expectation.obligations[0],source:{...source,start:0,end:text.length,quote:text}}];
 (f.expectation.obligations[0].expectedFacts as unknown[])=[{path:'board',value:'dinner_bed_breakfast',source}];
 f.plan.tasks=[{...f.plan.tasks[0],source:{attachmentId:'message:case',sourceHash:hash(text),page:1,start:0,end:text.length,quote:text}}];
 (f.plan.facts as unknown[])=[{kind:'board',value,source:{attachmentId:'message:case',sourceHash:hash(text),page:1,start:source.start,end:source.end,quote}}];
 f.runtime.tasks=f.runtime.tasks.slice(0,1);f.runtime.textBody=f.runtime.tasks[0].guestText;
 return f;
}
it.each(['dinner_bed_breakfast','DINNER, BED & BREAKFAST',{board:'DINNER, BED & BREAKFAST',roomRef:'1'},{board:'dinner_bed_breakfast',roomRef:'1'}])('matches a source-bound supported scalar or scoped board label: %j',async value=>{
 const result=await score(boardExpectationCase(value));expect(result.pass).toBe(true);expect(result.workComplete).toBe(false);expect(result.obligations[0].reasons).not.toContain('expected_fact_missing_or_mismatch');
});
it.each(['breakfast','room_only','dinner','DINNER, BED & BREAKFAST unless available'])('retains mismatched or unsupported board failures: %s',async value=>{
 const result=await score(boardExpectationCase(value));expect(result.pass).toBe(false);expect(result.obligations[0].reasons).toContain('expected_fact_missing_or_mismatch');
});
